INSERT INTO `defect_dictionaries` VALUES (1,'Length_Issue','Ukuran panjang roll atau lembaran material tidak sesuai dengan toleransi spesifikasi lembar order (terlalu pendek / berlebih).','Kalibrasi ulang sensor pencatat meter (counter) pada mesin rewinding/slitting dan verifikasi meter manual.','2026-10-12 02:53:56','2026-10-12 02:53:56'),(2,'Visual_Defect','Terdapat cacat tampilan fisik pada permukaan produk seperti bercak, bintik kotor, atau ketidaksesuaian visual.','Pembersihan ruang produksi (clean room filter) dan pemeriksaan kebersihan material sebelum proses.','2026-10-12 02:53:56','2026-10-12 02:53:56'),(3,'Deformation','Bentuk fisik roll menggelembung, melengkung (wavy), penyok, atau tidak presisi akibat tekanan tension yang tidak seimbang.','Atur ulang tension roll pada mesin rewinding & pastikan tumpukan palet di gudang tidak terlalu tinggi.','2026-10-12 02:53:56','2026-10-12 02:53:56'),(4,'ID_Issue','Diameter bagian dalam (Inner Diameter / Core) tidak pas dengan chuck mesin customer (longgar atau terlalu sempit).','Ukur diameter dalam core mengunakan Vernier Caliper terkalibrasi sebelum proses penggulungan.','2026-10-12 02:53:57','2026-10-12 02:53:57'),(5,'Adhesion_Issue','Daya rekat perekat (adhesive) lemah, melar, mudah terkelupas (delaminasi), atau tidak menempel sempurna.','Cek suhu oven dryer, rasio formula lem, dan ketebalan aplikasi adhesive secara berkala.','2026-10-12 02:53:57','2026-10-12 02:53:57'),(6,'Spec_Issue','Spesifikasi teknis material (gramatur, tipe film, atau tensile strength) tidak sesuai dengan Purchasing Order (PO).','Lakukan verifikasi Mill Test Certificate (MTC) dari supplier sebelum material diproses.','2026-10-12 02:53:57','2026-10-12 02:53:57'),(7,'Moisture_Issue','Kadar air (Moisture Content) pada bahan melampaui standar toleransi maksimum sehingga berpotensi lembap.','Pastikan humidity ruangan gudang terjaga (<60% RH) dan suhu oven pembakaran terkontrol.','2026-10-12 02:53:57','2026-10-12 02:53:57'),(8,'Thickness_Issue','Ketebalan lembaran produk tidak seragam (profil thickness uneven) antar bagian kiri, tengah, dan kanan.','Stel ulang celah die lip mesin extruder & bersihkan lip die dari kerak material.','2026-10-12 02:53:57','2026-10-12 02:53:57'),(9,'Rough_Cut','Hasil pemotongan pinggiran (cutting edge / trimming) kasar, berserabut, atau robek kecil.','Ganti pisau slitter yang tumpul dan atur sudut potong pisau potong (slitting blade).','2026-10-12 02:53:57','2026-10-12 02:53:57'),(10,'Printing_Defect','Hasil cetakan grafik/teks tidak presisi (miss-register), warna pudar, atau tidak tersablon.','Lakukan registrasi silinder cetak & periksa viskositas tinta cetak secara periodik.','2026-10-12 02:53:57','2026-10-12 02:53:57'),(11,'Surface_Damage','Kerusakan fisik bagian luar roll seperti terbentur, sobek luar, atau tergerus saat proses handling & kirim.','Gunakan bantal pelindung (corner protector) dan lapisi bungkus bubble wrap tebal pada tiap roll.','2026-10-12 02:53:57','2026-10-12 02:53:57');
/*!40000 ALTER TABLE `defect_dictionaries` ENABLE KEYS */;
UNLOCK TABLES;

